  2	  yearsWithMHPCO: number;
  3	}
  4	
  5	export interface Item {
  6	  type: string;
  7	  material?: string;
  8	  enchantment?: number;
  9	  cursed?: boolean;
 10	}
 11	
 12	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
 13	  sword: 100,
 14	  amulet: 60,
 15	  staff: 80,
 16	  potion: 40,
 17	};
 18	
 19	// Components (e.g. runes, moonstones) are not individually price-listed: they all
 20	// share one tariff, so the component roster is the single source of which types
 21	// are components and what each of them costs.
 22	const COMPONENT_TYPES = ["rune", "moonstone"];
 23	const COMPONENT_BASE_PREMIUM = 25;
 24	
 25	const BASE_PREMIUMS: Record<string, number> = {
 26	  ...MAIN_ITEM_BASE_PREMIUMS,
 27	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
 28	};
 29	
 30	const BLOCK_SIZE = 3;
 31	const BLOCK_BASE_PREMIUM = 60;
 32	
 33	// MHPCO reading of "alike": two items are alike exactly when their types match,
 34	// not merely when they belong to the same family (rune-y, gemstone-y).
 35	function countAlikeItems(items: Item[]): Map<string, number> {
 36	  const counts = new Map<string, number>();
 37	  for (const item of items) {
 38	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
 39	  }
 40	  return counts;
 41	}
 42	
 43	// A building block is offered for exactly 3 alike components.
 44	function blockOfferApplies(type: string, count: number): boolean {
 45	  return COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
 46	}
 47	
 48	// What the MHPCO is willing to insure at all: only item types on its price list. The
 49	// acceptance rule is enforced at the lookup every price enquiry must pass through, so no
 50	// part of a declined cover can be priced by any route.
 51	function listedBasePremium(type: string): number {
 52	  const basePremium = BASE_PREMIUMS[type];
 53	  if (basePremium === undefined) {
 54	    throw new Error(`MHPCO does not insure items of type "${type}"`);
 55	  }
 56	  return basePremium;
 57	}
 58	
 59	function typeBasePremium(type: string, count: number): number {
 60	  if (blockOfferApplies(type, count)) {
 61	    return BLOCK_BASE_PREMIUM;
 62	  }
 63	  return count * listedBasePremium(type);
 64	}
 65	
 66	function policyBasePremium(items: Item[]): number {
 67	  let total = 0;
 68	  for (const [type, count] of countAlikeItems(items)) {
 69	    total += typeBasePremium(type, count);
 70	  }
 71	  return total;
 72	}
 73	
 74	const CURSE_SURCHARGE = 0.5;
 75	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
 76	const HIGH_ENCHANTMENT_LEVEL = 5;
 77	
 78	function isHighlyEnchanted(item: Item): boolean {
 79	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
 80	}
 81	
 82	// Each risk factor the MHPCO recognises contributes its own rate; a cursed and
 83	// highly enchanted item is assessed both surcharges.
 84	function riskSurchargeRate(item: Item): number {
 85	  return (
 86	    (item.cursed === true ? CURSE_SURCHARGE : 0) +
 87	    (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0)
 88	  );
 89	}
 90	
 91	// Item-scoped risk surcharges are assessed against the affected item's own listed
 92	// base premium -- the block offer discounts the policy base premium only and does not
 93	// lower the surcharge base. Each item is rated separately and the results are summed.
 94	function itemScopedSurcharges(items: Item[]): number {
 95	  return items.reduce(
 96	    (total, item) => total + listedBasePremium(item.type) * riskSurchargeRate(item),
 97	    0,
 98	  );
 99	}
100	
101	const FIRST_INSURANCE_SURCHARGE = 0.1;
102	const LOYALTY_DISCOUNT = 0.2;
103	const LOYALTY_YEARS = 2;
104	
105	// Long-standing means at least LOYALTY_YEARS years of business. A discount, so it
106	// enters the policy-scoped rate as a negative rate.
107	function loyaltyRate(customer: Customer): number {
108	  return customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0;
109	}
110	
111	const FOLLOW_UP_DISCOUNT = 0.15;
112	
113	// Every contract after the customer's first earns the follow-up discount.
114	function followUpRate(previousContracts: number): number {
115	  return previousContracts > 0 ? -FOLLOW_UP_DISCOUNT : 0;
116	}
117	
118	// The MHPCO's policy-scoped tariff: each recognised policy-wide modifier contributes
119	// its own rate, and the rates are assessed together against the policy base premium.
120	//
121	// MHPCO reading of "a first insurance": the initial assessment is of the items newly
122	// brought in, not of the customer. Every quote is therefore a first insurance for the
123	// items it covers, so the surcharge is an unconditional term here -- it consults no
124	// customer history, and a long-standing customer on a follow-up contract is assessed
125	// it alongside the loyalty and follow-up discounts rather than instead of them.
126	function policyScopedRate(customer: Customer, previousContracts: number): number {
127	  return FIRST_INSURANCE_SURCHARGE + loyaltyRate(customer) + followUpRate(previousContracts);
128	}
129	
130	// Policy-scoped modifiers are assessed against the policy base premium alone -- the
131	// plain sum of the item base premiums, deliberately excluding item-scoped surcharges.
132	function policyScopedAdjustment(
133	  basePremium: number,
134	  customer: Customer,
135	  previousContracts: number,
136	): number {
137	  return basePremium * policyScopedRate(customer, previousContracts);
138	}
139	
140	const PROCESSING_FEE = 5;
141	
142	// Amounts are rounded in the MHPCO's favor, which means opposite directions on the two
143	// sides of the ledger: a premium the MHPCO collects rounds up, a payout it owes rounds
144	// down. Both tolerate the same floating-point slack so that an amount computed as
145	// exactly 197.5 or 350.5 is not pushed across the boundary by representation error.
146	const AMOUNT_PRECISION = 1e-9;
147	
148	function roundUpInMHPCOFavor(amount: number): number {
149	  return Math.ceil(amount - AMOUNT_PRECISION);
150	}
151	
152	// How the MHPCO closes a premium: the processing fee is added at the very end, after
153	// every percentage modifier, and only that final figure is rounded -- intermediate
154	// amounts stay fractional, and rounding always favours the MHPCO.
155	function closedPremium(modifiedPremium: number): number {
156	  return roundUpInMHPCOFavor(modifiedPremium + PROCESSING_FEE);
157	}
158	
159	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
160	  const basePremium = policyBasePremium(items);
161	  return closedPremium(
162	    basePremium +
163	      itemScopedSurcharges(items) +
164	      policyScopedAdjustment(basePremium, customer, previousContracts),
165	  );
166	}
