168	export interface Damage {
169	  itemType: string;
170	  amount: number;
171	}
172	
173	export interface Incident {
174	  cause: string;
175	  damages: Damage[];
176	}
177	
178	export interface ClaimSettlement {
179	  payout: number;
180	  remainingCap: number;
181	}
182	
183	const DEDUCTIBLE = 100;
184	
185	function roundDownInMHPCOFavor(amount: number): number {
186	  return Math.floor(amount + AMOUNT_PRECISION);
187	}
188	
189	// Each damage event bears its own deductible.
190	function reimbursement(damage: Damage): number {
191	  return damage.amount - DEDUCTIBLE;
192	}
193	
194	// What the MHPCO owes for an incident: every damage in it is reimbursed on its own terms
195	// and the reimbursements are added up. One incident can damage several insured items, and
196	// the deductible bites per damage rather than per incident.
197	function incidentReimbursement(damages: Damage[]): number {
198	  return damages.reduce((total, damage) => total + reimbursement(damage), 0);
199	}
200	
201	export function claim(items: Item[], incident: Incident): ClaimSettlement {
202	  // remainingCap is a provisional 0: the insurance sum and the twice-the-sum cap are not
203	  // behaviors of this module yet, so no cap has been assessed to report a remainder of.
204	  return {
205	    payout: roundDownInMHPCOFavor(incidentReimbursement(incident.damages)),
206	    remainingCap: 0,
207	  };
208	}

